'use strict';
const $=id=>document.getElementById(id),R=ExtendedRecord,gate=new R.RunGate();let worker=null,sequence=0,snapshot=null,runInput=null,start=0,operationEpoch=0;
const f=x=>Number.isFinite(x)?x.toPrecision(6):'unavailable';
function generate(){invalidate('Channel changed. Run to calculate a new result.');$('channel').value=JSON.stringify(R.seeded(Number($('nt').value),Number($('seed').value)),null,2);}
function invalidate(message){operationEpoch++;if(gate.current&&worker)worker.postMessage({type:'cancel',runId:gate.current});gate.clear();clearResult();$('cancel').disabled=true;if(message)$('status').textContent=message;}
function clearResult() {snapshot=null;$('export').disabled=true;$('output').replaceChildren();$('origin').textContent='No completed result for the current run';}
function node(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function card(title,m,feasible,imported){const el=node('article',undefined,'card');el.append(node('h3',title),node('p',feasible?(imported?'Recorded feasibility checks passed':'Feasibility checks passed'):(imported?'Recorded: not accepted feasible':'Not an accepted feasible design'),'badge'+(feasible?'':' warn')),node('p','Full-response complex-MSE bound'),node('div',f(m.radar.fullResponseMseBound),'number'));const dl=node('dl');for(const [k,v] of [['Worst SINR (linear)',f(Math.min(...m.users.map(u=>u.sinr)))],['Worst SINR / threshold',f(Math.min(...m.users.map(u=>u.ratioToThreshold)))],['Used power (mW)',f(m.powerMw)],['Inverse trace (1/mW)',f(m.radar.traceInversePerMw)],['Covariance',m.radar.status]])dl.append(node('dt',k),node('dd',v));el.append(dl,node('h4','R eigenvalues (mW)'));const bars=node('div',undefined,'spectrum'),ev=m.radar.eigenvaluesMw,max=Math.max(...ev,1);bars.setAttribute('aria-hidden','true');ev.forEach(v=>{const bar=node('div',undefined,'bar');bar.style.height=Math.max(0,v)/max*100+'%';bars.append(bar);});el.append(bars,node('p',ev.map(f).join(' · '),'values'),node('h4','Received power decomposition (mW)'));const sc=node('div',undefined,'scroll'),table=node('table'),tr=node('tr');['User','Desired','Other data','Probing','Noise'].forEach(v=>tr.append(node('th',v)));const head=node('thead');head.append(tr);table.append(head);const body=node('tbody');m.users.forEach((u,i)=>{const row=node('tr');[i+1,f(u.desiredMw),f(u.dataInterferenceMw),f(u.probingInterferenceMw),'1'].forEach(v=>row.append(node('td',v)));body.append(row);});table.append(body);sc.append(table);el.append(sc);return el;}
function render(env,imported){snapshot=env;$('export').disabled=false;const r=env.record;$('origin').textContent=(imported?'IMPORTED SAVED RECORD · not recalculated; structurally validated, not independently recertified':'LIVE WORKER RESULT')+' · '+env.runId+' · Nt '+env.input.Nt+' · Γ '+env.input.gammaDb+' dB';$('output').replaceChildren();const out=$('output');out.append(node('p',(imported?'Recorded status: ':'Status: ')+r.status+' · '+(imported?'recorded physical gate: ':'physical gate: ')+(r.physicalGate.passed?'passed':'not passed'),'badge'+(r.physicalGate.passed?'':' warn')));if(r.failureReason)out.append(node('p',typeof r.failureReason==='string'?r.failureReason:JSON.stringify(r.failureReason)));if(r.diagnosticsFailureReason)out.append(node('p','Optional diagnostics unavailable: '+r.diagnosticsFailureReason));if(r.physicalGate.failures?.length)out.append(node('p','Gate findings: '+r.physicalGate.failures.join(', ')));if(r.certificate)out.append(node('p',(imported?'Recorded floating-point certificate':'Floating-point certificate')+' · relative gap '+f(r.certificate.relativeGap)+' · coefficient residual '+f(r.certificate.epigraphCoefficientResidual)));if(r.recovery)out.append(node('p','Recovered covariance relative defect: '+f(r.recovery.covarianceRelativeDefect)));if(r.metrics&&r.baseline){const box=node('div',undefined,'comparison');box.append(card('Constructive recovery',r.metrics,r.status==='converged'&&r.physicalGate.passed,imported),card('Principal-eigenpair baseline',r.baseline.metrics,r.baseline.feasible,imported));out.append(box,node('p','Baseline: same relaxed data blocks; original probing retained; no power rescaling. Compare used power as well as feasibility.','small'));}else out.append(node('p','No accepted beam comparison is available for this terminal state. A cap or cancellation does not establish infeasibility.'));}
function ensureWorker(){if(worker)return worker;worker=new Worker('worker.js');worker.onmessage=({data:m})=>{if(!gate.accept(m))return;if(m.type==='progress'){$('status').textContent='Running '+m.runId+' · iteration '+m.progress.iterations;return;}if(m.type==='started')return;$('cancel').disabled=true;gate.clear();if(m.type==='error'){$('status').textContent='Worker error: '+m.message;return;}try{render(R.create(m.runId,runInput,m.record),false);$('status').textContent='Finished: '+m.record.status+' · Worker wall time '+(m.workerWallMs/1000).toFixed(2)+' s · observed browser wall time '+((performance.now()-start)/1000).toFixed(2)+' s (includes scheduling and transport; not a benchmark)';}catch(e){clearResult();$('status').textContent='Result validation failed: '+e.message;}};worker.onerror=e=>{gate.clear();clearResult();$('cancel').disabled=true;$('status').textContent='Worker could not run: '+e.message+'. Serve this directory over HTTP(S), not file://.';worker.terminate();worker=null;};return worker;}
$('form').onsubmit=e=>{e.preventDefault();try{const nt=Number($('nt').value),input=R.input({Nt:nt,Nr:nt+4,K:2,L:30,powerMw:1000,communicationNoiseMw:1,radarNoiseMw:1,gammaDb:Number($('gamma').value),H:JSON.parse($('channel').value)});const w=ensureWorker();operationEpoch++;runInput=R.freeze(JSON.parse(JSON.stringify(input)));const id='run-'+Date.now()+'-'+(++sequence);gate.begin(id);clearResult();start=performance.now();$('cancel').disabled=false;$('status').textContent='Starting '+id;w.postMessage({type:'run',runId:id,input:runInput});}catch(e){invalidate('Input error: '+e.message);}};
$('cancel').onclick=()=>{if(gate.current){worker.postMessage({type:'cancel',runId:gate.current});$('status').textContent='Cancellation requested; waiting for Worker acknowledgement';$('cancel').disabled=true;}};
$('generate').onclick=generate;$('nt').onchange=generate;for(const id of ['gamma','channel','seed'])$(id).oninput=()=>invalidate('Inputs changed. Run to calculate a new result.');window.addEventListener('pagehide',()=>{invalidate('Page left; previous work cleared. Run again after returning.');if(worker){worker.terminate();worker=null;}});
$('export').onclick=()=>{if(!snapshot)return;const url=URL.createObjectURL(new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'})),a=node('a');a.href=url;a.download='extended-crb-'+snapshot.runId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('import').onchange=async e=>{const file=e.target.files[0];if(!file)return;const epoch=++operationEpoch;try{if(file.size>5000000)throw Error('File exceeds 5 MB');const text=await file.text();if(epoch!==operationEpoch)return;const env=R.parse(text);if(gate.current)worker.postMessage({type:'cancel',runId:gate.current});gate.clear();$('cancel').disabled=true;render(env,true);$('status').textContent='Imported immutable record. Import does not run or independently verify the solver.';}catch(err){if(epoch===operationEpoch)$('status').textContent='Import rejected: '+err.message;}finally{if(epoch===operationEpoch)e.target.value='';}};
generate();
